package dev.shadw.asgard.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Fenrir, the Bound Wolf with its own model and texture. Generated by shadw-mod mob. */
public class FenrirRenderer extends MobRenderer<Fenrir, FenrirModel.State, FenrirModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("asgard", "textures/entity/fenrir.png");

	public FenrirRenderer(EntityRendererProvider.Context context) {
		super(context, new FenrirModel(context.bakeLayer(FenrirModel.LAYER)), 1.2F);
	}

	@Override
	public FenrirModel.State createRenderState() {
		return new FenrirModel.State();
	}

	@Override
	public void extractRenderState(Fenrir entity, FenrirModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(FenrirModel.State state) {
		return TEXTURE;
	}
}
